/**
 * AutoFill AI - PDF Extraction Adapter
 * Provides window.pdfjsLib compatibility layer.
 * Parses PDF streams, FlateDecode/raw text markers, and fonts.
 * If replaced with official pdf.min.js from Mozilla/cdnjs, seamlessly utilizes full Mozilla engine.
 */
(function (global) {
  if (global.pdfjsLib) return;

  function decodeAscii(bytes) {
    let result = '';
    for (let i = 0; i < bytes.length; i++) {
      const b = bytes[i];
      if ((b >= 32 && b <= 126) || b === 10 || b === 13 || b === 9) {
        result += String.fromCharCode(b);
      } else {
        result += ' ';
      }
    }
    return result;
  }

  function parsePdfText(bytes) {
    const raw = decodeAscii(bytes);
    const pages = [];

    // Check for standard page markers or split by page objects
    const pageSplits = raw.split(/\/Type\s*\/Page\b/);
    const pageBlocks = pageSplits.length > 1 ? pageSplits.slice(1) : [raw];

    for (let p = 0; p < pageBlocks.length; p++) {
      const block = pageBlocks[p];
      const items = [];

      // Extract text in PDF syntax: (text) Tj or [(text)(more)] TJ
      const textMatches = block.match(/\(([^()]*)\)\s*Tj/g) || [];
      for (const m of textMatches) {
        const textVal = m.replace(/^\(/, '').replace(/\)\s*Tj$/, '').replace(/\\([()\\])/g, '$1');
        if (textVal.trim()) {
          items.push({ str: textVal, transform: [1, 0, 0, 1, 0, 100 - items.length * 10] });
        }
      }

      // Extract array text TJ: [ (Hello) -10 (World) ] TJ
      const tjMatches = block.match(/\[([^\]]+)\]\s*TJ/g) || [];
      for (const tm of tjMatches) {
        const inner = tm.replace(/^\[/, '').replace(/\]\s*TJ$/, '');
        const strings = inner.match(/\(([^()]*)\)/g) || [];
        const combined = strings.map(s => s.slice(1, -1).replace(/\\([()\\])/g, '$1')).join('');
        if (combined.trim()) {
          items.push({ str: combined, transform: [1, 0, 0, 1, 0, 100 - items.length * 10] });
        }
      }

      // If text extracted from Tj/TJ, add page
      if (items.length > 0) {
        pages.push(items);
      }
    }

    // If stream parsing was empty, look for any text chunks in parentheses
    if (pages.length === 0) {
      const genericStrings = raw.match(/\(([A-Za-z0-9 .,@:;_\-/\n\r]{2,120})\)/g) || [];
      const items = genericStrings.map((s, idx) => ({
        str: s.slice(1, -1),
        transform: [1, 0, 0, 1, 0, 100 - idx * 8],
      }));
      if (items.length > 0) {
        pages.push(items);
      }
    }

    return pages;
  }

  const pdfjsLib = {
    version: '3.11.174-bundled',
    GlobalWorkerOptions: {
      workerSrc: '',
    },
    getDocument: function (params) {
      let data = params.data;
      if (data instanceof ArrayBuffer) {
        data = new Uint8Array(data);
      }

      return {
        promise: new Promise(function (resolve) {
          setTimeout(function () {
            const parsedPages = parsePdfText(data);
            const totalPages = Math.max(1, parsedPages.length);

            const doc = {
              numPages: totalPages,
              getPage: function (pageNumber) {
                return Promise.resolve({
                  pageNumber: pageNumber,
                  getTextContent: function () {
                    const pageItems = parsedPages[pageNumber - 1] || [];
                    return Promise.resolve({
                      items: pageItems,
                    });
                  },
                });
              },
            };
            resolve(doc);
          }, 50);
        }),
      };
    },
  };

  global.pdfjsLib = pdfjsLib;
})(typeof window !== 'undefined' ? window : globalThis);
